def _load():
    for path in pathlib.Path(".").rglob("*.py"):
        try:
            txt = path.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        if "class CORSMiddleware" in txt:
            spec = importlib.util.spec_from_file_location("cors_under_test", str(path))
            mod = importlib.util.module_from_spec(spec)
            try:
                spec.loader.exec_module(mod)
                return mod.CORSMiddleware
            except Exception:
                continue
    raise ImportError("CORSMiddleware not found")
CORSMiddleware = _load()

def test_exact_allowed():
    m = CORSMiddleware(allowed_origins=["https://example.com"])
    assert m.is_origin_allowed("https://example.com") is True

def test_suffix_without_dot_blocked():
    m = CORSMiddleware(allowed_origins=["https://example.com"])
    assert m.is_origin_allowed("https://evil-example.com") is False
    assert m.is_origin_allowed("https://example.com.evil.com") is False
    assert m.is_origin_allowed("https://sub.example.com") is False

def test_wildcard_sub_allowed_apex_denied():
    m = CORSMiddleware(allowed_origins=["*.example.com"])
    assert m.is_origin_allowed("https://sub.example.com") is True
    assert m.is_origin_allowed("https://example.com") is False
    assert m.is_origin_allowed("https://evil-example.com") is False
    assert m.is_origin_allowed("https://example.com.evil.com") is False
    assert m.is_origin_allowed("https://sub.example.com.evil.com") is False

def test_scheme_wildcard():
    m = CORSMiddleware(allowed_origins=["https://*.example.com"])
    assert m.is_origin_allowed("https://sub.example.com") is True
    assert m.is_origin_allowed("https://sub.example.com:8080") is True
    assert m.is_origin_allowed("http://sub.example.com") is False
    assert m.is_origin_allowed("https://evil.com") is False
    assert m.is_origin_allowed("https://sub.example.com.evil.com") is False

def test_null_denied():
    m = CORSMiddleware(allowed_origins=["https://example.com", "*.example.com"])
    assert m.is_origin_allowed("") is False
    assert m.is_origin_allowed(None) is False
    assert m.is_origin_allowed("null") is False

def test_preflight_only_allowed():
    m = CORSMiddleware(allowed_origins=["https://example.com"])
    assert m.handle_preflight("https://evil.com", "GET") == {}
    h = m.handle_preflight("https://example.com", "GET")
    assert h.get("Access-Control-Allow-Origin") == "https://example.com"
    assert m.get_cors_headers("https://evil.com") == {}
